window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6bc630b1b43cab5c"]={"versions": [{"id": "FIG-6bc630b1b43cab5c", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Dateistruktur-Diagramm aus der AUTOSAR-Spezifikation des Moduls <em>Memory Mapping</em> (SWS MemoryMapping). Das Diagramm veranschaulicht auf Architekturebene die Einbindungsbeziehung zwischen einem AUTOSAR Basic Software (BSW) Modul und seiner modulspezifischen Memory-Mapping-Header-Datei.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>«header» {Mip}_MemMap.h</strong>: Artefakt / Header-Datei für das modulspezifische Speichergruppierungs-Mapping des BSW-Moduls.\n</li><li><strong>BSW module</strong>: Repräsentiert das Quellcode- bzw. Implementierungsartefakt eines konkreten AUTOSAR-Basissoftwaremoduls.\n</li><li><strong>«includes»</strong>: Gerichtete gestrichelte Abhängigkeitsbeziehung (Dependency/Usage) vom <code>BSW module</code> auf <code>{Mip}_MemMap.h</code>, die die <code>#include</code>-Direktive zur Kompilierzeit abbildet.\n</li><li><strong>Textuelle Notation / Nomenklatur</strong>:\n<ul class=\"fig-list\"><li><code>• &lt;ai&gt; is the vendorApiInfix of the BSW module</code>\n</li><li>Erläuternder Text: <em>The sub part in squared brackets <code>[_&lt;vi&gt;_&lt;ai&gt;]</code> is omitted if no vendorApiInfix is defined for the Basic Software Module which indicates that it does not use multiple instantiation.</em>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Inklusionsverhältnis zur Kompilierzeit. Das Quellcode-Artefakt des BSW-Moduls inkludiert die Header-Datei <code>{Mip}_MemMap.h</code> wiederholt (bzw. umschließend für Code-, Konstanten- oder Variablensektionen), um über Präprozessormakros Speicherabschnitte zuzuordnen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Richtlinie zur Modulstrukturierung: Jedes BSW-Modul bindet seine modulspezifische Memory-Mapping-Header-Datei <code>{Mip}_MemMap.h</code> ein. Der Dateiname setzt sich aus dem Modul-Infix <code>{Mip}</code> zusammen. Falls das Modul keine Mehrfachinstanziierung verwendet bzw. kein <code>vendorApiInfix</code> deklariert ist, entfällt der optionale Namensbestandteil <code>[_&lt;vi&gt;_&lt;ai&gt;]</code>.</p>"}, {"id": "FIG-822de02a6365d0fa", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Dateistruktur-Diagramm aus der AUTOSAR-Spezifikation des Moduls <em>Memory Mapping</em> (SWS MemoryMapping). Das Diagramm veranschaulicht auf Architekturebene die Einbindungsbeziehung zwischen einem AUTOSAR Basic Software (BSW) Modul und seiner modulspezifischen Memory-Mapping-Header-Datei.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>«header» {Mip}_MemMap.h</strong>: Artefakt / Header-Datei für das modulspezifische Speichergruppierungs-Mapping des BSW-Moduls.\n</li><li><strong>BSW module</strong>: Repräsentiert das Quellcode- bzw. Implementierungsartefakt eines konkreten AUTOSAR-Basissoftwaremoduls.\n</li><li><strong>«includes»</strong>: Gerichtete gestrichelte Abhängigkeitsbeziehung (Dependency/Usage) vom <code>BSW module</code> auf <code>{Mip}_MemMap.h</code>, die die <code>#include</code>-Direktive zur Kompilierzeit abbildet.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Inklusionsverhältnis zur Kompilierzeit. Das Quellcode-Artefakt des BSW-Moduls inkludiert die Header-Datei <code>{Mip}_MemMap.h</code> wiederholt (bzw. umschließend für Code-, Konstanten- oder Variablensektionen), um über Präprozessormakros Speicherabschnitte zuzuordnen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Richtlinie zur Modulstrukturierung: Jedes BSW-Modul bindet seine modulspezifische Memory-Mapping-Header-Datei <code>{Mip}_MemMap.h</code> ein. Der Dateiname verwendet das Modul-Infix <code>{Mip}</code> zur eindeutigen Zuordnung des Speicher-Mappings auf BSW-Ebene.</p>"}], "trans": [{"from": "FIG-6bc630b1b43cab5c", "to": "FIG-822de02a6365d0fa", "fr": "R4.1.3", "tr": "R4.2.2", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Der oberhalb der UML-Artefakte platzierte erläuternde Fließtext zur Namenskonvention (<code>• &lt;ai&gt; is the vendorApiInfix of the BSW module</code> und die Bemerkung zur Auslassung von <code>[_&lt;vi&gt;_&lt;ai&gt;]</code>) wurde aus der Bildgrafik entfernt.\n</li><li>Die UML-Komponenten-Darstellung selbst (<code>BSW module</code> inkludiert via <code>«includes»</code> <code>«header» {Mip}_MemMap.h</code>) bleibt unverändert.\n</li></ul>"}]};
